{"command":"python3 - <<'PY'
import pandas as pd, numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter

def annual_from_table(path):
    df=pd.read_excel(path,header=None)
    annual={}
    for _, row in df.iterrows():
        y=str(row[0]).strip()
        if y.endswith('.') and ':' not in y and y[:4].isdigit():
            annual[int(y[:4])] = float(row[1])
    # quarterly 2024 values in rows starting with 2024 or indented continuation until footnote/source
    q=[]
    seen=False
    for _, row in df.iterrows():
        y=str(row[0])
        if y.startswith('2024:'):
            seen=True
        if seen:
            y2=y.strip()
            if y2.startswith(('2024:','II.','III','IV.')) or y2 in ['II.','III.','IV.'] or y.startswith('    '):
                try:
                    q.append(float(row[1]))
                except:
                    pass
    annual[2024]=sum(q)/len(q)
    return annual

pce=annual_from_table('/root/ERP-2025-table10.xls')
pfi=annual_from_table('/root/ERP-2025-table12.xls')
print(pce[2024], pfi[2024])
# build cpi
cpi=pd.read_excel('/root/CPI.xlsx',header=None)
cpi_map={int(r[0]): float(r[1]) for _,r in cpi.iterrows() if str(r[0]).isdigit()}
years=range(1973,2025)
pce_real=np.array([pce[y]/cpi_map[y] for y in years])
pfi_real=np.array([pfi[y]/cpi_map[y] for y in years])
pc,_=hpfilter(np.log(pce_real),lamb=100)
fc,_=hpfilter(np.log(pfi_real),lamb=100)
print(np.corrcoef(pc,fc)[0,1])
PY"}
